  public static void ValidateObjectTarget(ObjectSaveBridge.Prepared state){if(state==null)throw new InvalidOperationException("Missing object snapshot.");var flags=BindingFlags.Instance|BindingFlags.NonPublic;var trees=(TreeInstance[])typeof(ObjectSaveBridge.Prepared).GetField("Trees",flags).GetValue(state);var props=(PropInstance[])typeof(ObjectSaveBridge.Prepared).GetField("Props",flags).GetValue(state);var tg=(uint[])typeof(ObjectSaveBridge.Prepared).GetField("TreeGrid",flags).GetValue(state);var pg=(ushort[])typeof(ObjectSaveBridge.Prepared).GetField("PropGrid",flags).GetValue(state);int grid=(int)typeof(PackedObjectPosition).Assembly.GetType("HundredTiles.Core.ExpandedMap").GetField("GridSize").GetRawConstantValue();if(trees==null || trees.Length<ExpandedObjects.MinimumTrees || trees.Length>ExpandedObjects.MaximumTrees || trees.Length!=Singleton<TreeManager>.instance.m_trees.m_buffer.Length || props==null || props.Length!=ExpandedObjects.Props || props.Length!=Singleton<PropManager>.instance.m_props.m_buffer.Length || tg==null || pg==null || tg.Length!=grid*60*grid*60 || pg.Length!=grid*30*grid*30 || Singleton<TreeManager>.instance.m_treeGrid.Length!=tg.Length || Singleton<PropManager>.instance.m_propGrid.Length!=pg.Length)throw new InvalidOperationException("Expanded object restore targets differ.");}
