   if(assembly.GetName().Name=="PropControl"){ReviewedOverlays.VerifyModule(assembly);var type=assembly.GetType("PropControl.Patches.PropInstancePatches",true);precision=type.GetField("PrecisionData",BindingFlags.Static|BindingFlags.NonPublic);if(precision==null)throw new InvalidOperationException("Prop Control precision table changed.");hooks.Add(new HookSpec{Target=assembly.GetType("PropPrecision.Data",true).GetMethod("Deserialize"),Postfix=typeof(SpatialAdapters).GetMethod("PrecisionLoaded")});hooks.Add(new HookSpec{Target=typeof(PropInstance).GetMethod("get_Position"),Prefix=typeof(SpatialAdapters).GetMethod("NativePropGet")});hooks.Add(new HookSpec{Target=typeof(PropInstance).GetMethod("set_Position"),Prefix=typeof(SpatialAdapters).GetMethod("NativePropSet")});}
